// --- n8n wrapper: ZoomInfo usage/credit check via Bearer token (CLOUD split-code-node) ---
const USAGE_URL = "https://api.zoominfo.com/gtm/data/v1/users/usage";
const sd = $getWorkflowStaticData("global");
const items = $input.all();
const out = [];
for (const item of items) {
  const token = item.json.zoom_token;
  if (!token) { out.push({ json: { error: "no zoominfo token available (mint failed or missing)" } }); continue; }
  let res;
  try {
    res = await this.helpers.httpRequest({
      method: "GET", url: USAGE_URL,
      headers: { Authorization: "Bearer " + token, Accept: "application/vnd.api+json" },
    });
  } catch (e) {
    if (isAuthError(extractErrorStatus(e))) {
      delete sd.zoominfo;  // token rejected -> clear cache so the NEXT run re-mints
    }
    res = { error: String((e && e.message) || e) };
  }
  out.push({ json: res });
}
return out;

// n8n/code/providerSelection.js — pure-JS provider-selection cost gate for n8n Code nodes.
//
// Phase 16.1: the caller-supplied `providers` webhook field is the PRIMARY burn gate
// (CONTEXT Locked Decision 1 — no global build-time kill-switch). This module is pure,
// deterministic, and carries NO n8n globals — mirrors enrichmentGate.js exactly, inlined
// into Code nodes via the builder's inline() (Code nodes cannot require() siblings).
//
// parseWebhookBody(body)
//   -> { events, providers }
//   Explicit payload contract (reviews A4): a bare HubSpot event array carries no
//   top-level `providers` slot; an envelope `{ providers, events: [...] }` object carries
//   the caller's selection at the envelope level. A single bare event object (neither an
//   array nor an envelope with `.events`) is treated as the one event, and its own
//   `.providers` field (if any) IS the envelope-level providers value here — the n8n
//   wrapper additionally falls back to `event.providers` per-event when this returns
//   undefined (`parsed.providers ?? event.providers`), covering the same single-event case
//   without double logic.
//
// resolveEnabledProviders(raw, allNames)
//   -> { provider_enabled: { <name>: boolean, ... }, providers_requested: [...] }
//   "all"                    -> every name in allNames enabled
//   "none" / "" / null / undefined / anything else (absent/unrecognized) -> none enabled
//   an array                 -> exactly those names (lowercased, intersected with
//                                allNames; unknown names dropped)
//
// extractCredits(provider, raw)
//   -> number | null
//   Three null-safe per-provider credit extractors (RESEARCH.md Task 1, live-curl-
//   validated). Forward-provisioned here for Plan 02 (16.1 does not call this at
//   runtime); unit-tested now so Plan 02 can consume it with zero further verification.
//   Every extractor returns null on ANY shape mismatch — never throws, never fails the run.

function parseWebhookBody(body) {
  const events = Array.isArray(body)
    ? body
    : (body && Array.isArray(body.events) ? body.events : [body]);
  const providers = (body && !Array.isArray(body)) ? body.providers : undefined;
  return { events, providers };
}

function resolveEnabledProviders(raw, allNames) {
  const all = Array.isArray(allNames) ? allNames : [];
  const allLower = all.map((n) => String(n).toLowerCase());
  let enabledLower;

  if (raw === "all") {
    enabledLower = allLower.slice();
  } else if (Array.isArray(raw)) {
    const requestedLower = raw.map((n) => String(n).toLowerCase());
    enabledLower = allLower.filter((n) => requestedLower.indexOf(n) !== -1);
  } else {
    // "none" | "" | null | undefined | any other unrecognized value -> nothing enabled
    // (CONTEXT Locked Decision 2 — safe default, explicit opt-in required).
    enabledLower = [];
  }

  const enabledSet = new Set(enabledLower);
  const provider_enabled = {};
  const providers_requested = [];
  for (const name of all) {
    const lower = String(name).toLowerCase();
    const isEnabled = enabledSet.has(lower);
    provider_enabled[name] = isEnabled;
    if (isEnabled) providers_requested.push(name);
  }

  return { provider_enabled, providers_requested };
}

function extractCredits(provider, raw) {
  const p = String(provider || "").toLowerCase();

  if (p === "lusha") {
    // 200 body -> { credits: { total, used, remaining } } [VERIFIED: live curl 200]
    return (raw && raw.credits && typeof raw.credits.remaining === "number")
      ? raw.credits.remaining : null;
  }

  if (p === "apollo") {
    // THIS account's key 403s (non-master) [VERIFIED: live curl 403] -> raw carries no
    // `remaining` field -> null. A master key's usage_stats body (undocumented shape for
    // this account) is read defensively: only a top-level numeric `remaining` is trusted.
    return (raw && typeof raw.remaining === "number") ? raw.remaining : null;
  }

  if (p === "zoominfo") {
    // JSON:API: data[0].attributes.usage[] keyed by limitType. [VERIFIED: live curl 200]
    // The real redeemable-records balance lives under limitType === "uniqueIdLimit";
    // fall back to the first entry with a non-zero totalLimit before giving up (Open
    // Question #1 — a different ZoomInfo plan may report its balance under another key).
    const usage = (raw && raw.data && raw.data[0] && raw.data[0].attributes
      && raw.data[0].attributes.usage) || [];
    if (!Array.isArray(usage)) return null;
    let entry = usage.find((u) => u && u.limitType === "uniqueIdLimit");
    if (!entry) entry = usage.find((u) => u && typeof u.totalLimit === "number" && u.totalLimit > 0);
    return (entry && typeof entry.usageRemaining === "number") ? entry.usageRemaining : null;
  }

  return null;
}

// --- n8n wrapper: Build Credit Status (Phase 25 Plan 02) ---
function nodeAll(name) { try { return $(name).all(); } catch (e) { return []; } }
function httpStatus(raw) {
  if (!raw) return null;
  const candidates = [raw.statusCode, raw.httpCode, raw.status,
    raw.response && raw.response.status, raw.response && raw.response.statusCode];
  for (const c of candidates) {
    if (c !== undefined && c !== null && c !== "") {
      const n = Number(c);
      if (Number.isFinite(n)) return n;
    }
  }
  return null;
}
const first = $('Status Credit Request').first();
const providers_requested = (first && first.json && first.json.providers_requested) || [];
const CREDIT_NODE_BY_PROVIDER = { lusha: "Lusha Usage", apollo: "Apollo Usage", zoominfo: "ZoomInfo Usage" };
const balances = providers_requested.map((provider) => {
  const nodeName = CREDIT_NODE_BY_PROVIDER[provider];
  const rows = nodeName ? nodeAll(nodeName) : [];
  const row = rows[0];
  const raw = row && row.json;
  const status = httpStatus(raw);
  let credits = null;
  let error = null;
  if (!row) {
    error = "not_executed";
  } else if (raw && raw.error) {
    error = status ? ("http_" + status) : "provider_error";
  } else {
    credits = extractCredits(provider, raw);
    if (credits === null) error = "unrecognized_response_shape";
  }
  return { provider, configured: true, credits, unreadable: credits === null, error, status };
});
return [{ json: { balances, checked_at: new Date().toISOString() } }];

// n8n/code/backendStatus.js — pure-JS null-safe extraction and credential-health
// derivation for the `hubspot/backend-status` endpoint's full-health slice (Phase 27).
//
// Mirrors providerSelection.js exactly: no n8n globals, no require() of siblings, every
// exported function total and non-throwing. Inlined into Code nodes via the builder's
// inline() (Code nodes cannot require() siblings).
//
// extractSearchTotal(raw)
//   -> number | null
//   Reads a HubSpot CRM v3 search response's `.total` field. Every shape mismatch
//   (non-object, missing field, non-numeric, boolean) yields null — a genuine numeric
//   zero is the ONLY input that returns 0 (D-08: unknown is never zero).
//
// deriveSourceHealth(probe)
//   -> { state: "ok" | "refused" | "unknown", status: number|null, reason: string|null }
//   `probe` is `{configured, status, value}` for one credential-bearing source. A non-2xx
//   status can NEVER produce "ok" (T-27-04); an unconfigured/unreachable source produces
//   "unknown", distinct from "refused" (D-08 — an absent credential is not a refusal).
//
// buildStatusBody(parts)
//   -> { counts: {...}, credential_health: [...], checked_at }
//   Assembles the response, preserving `null` counts as JSON null (STATUS-06) — never 0,
//   never an omitted key. Never throws; every malformed branch degrades to unknown/null.

function extractSearchTotal(raw) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) return null;
  const total = raw.total;
  if (typeof total !== "number" || !Number.isFinite(total)) return null;
  return total;
}

function deriveSourceHealth(probe) {
  const p = probe && typeof probe === "object" ? probe : {};
  const configured = p.configured === true;
  const status = typeof p.status === "number" && Number.isFinite(p.status) ? p.status : null;

  if (!configured) {
    // No credential to probe with at all — cannot-tell, never "refused" (D-08).
    return { state: "unknown", status: null, reason: "not_configured" };
  }
  if (status === null) {
    // Configured but no usable status came back (timeout, not executed, malformed shape).
    return { state: "unknown", status: null, reason: "no_response" };
  }
  if (status >= 200 && status < 300) {
    if (p.value === null || p.value === undefined) {
      // A 2xx with no usable value is still a "can't tell," never a false "ok".
      return { state: "unknown", status, reason: "unrecognized_response_shape" };
    }
    return { state: "ok", status, reason: null };
  }
  // Any non-2xx (401/403/429/5xx/...) is reachable-but-refused — never "ok".
  return { state: "refused", status, reason: "http_" + status };
}

function buildStatusBody(parts) {
  const safe = parts && typeof parts === "object" && parts !== null ? parts : {};
  const counts = safe.counts && typeof safe.counts === "object" ? safe.counts : {};
  const health = Array.isArray(safe.health) ? safe.health : [];

  const normCount = (v) => (typeof v === "number" && Number.isFinite(v) ? v : null);

  return {
    counts: {
      companies_requested_unresolved: normCount(counts.companies_requested_unresolved),
      companies_awaiting_review: normCount(counts.companies_awaiting_review),
      contacts_requested_unresolved: normCount(counts.contacts_requested_unresolved),
      contacts_awaiting_review: normCount(counts.contacts_awaiting_review),
    },
    credential_health: health.map((h) => {
      const entry = h && typeof h === "object" ? h : {};
      const state = entry.state === "ok" || entry.state === "refused" ? entry.state : "unknown";
      return {
        source: typeof entry.source === "string" ? entry.source : "unknown",
        state,
        status: typeof entry.status === "number" ? entry.status : null,
        reason: typeof entry.reason === "string" ? entry.reason : null,
      };
    }),
    checked_at: typeof safe.checked_at === "string" ? safe.checked_at : new Date().toISOString(),
  };
}

// --- n8n wrapper: Build Status (Phase 27 Plan 01) ---
function nodeAll(name) { try { return $(name).all(); } catch (e) { return []; } }
function httpStatus(raw) {
  if (!raw) return null;
  const candidates = [raw.statusCode, raw.httpCode, raw.status,
    raw.response && raw.response.status, raw.response && raw.response.statusCode];
  for (const c of candidates) {
    if (c !== undefined && c !== null && c !== "") {
      const n = Number(c);
      if (Number.isFinite(n)) return n;
    }
  }
  return null;
}
// A search node's own probe outcome IS its credential-health signal (Pitfall 1) —
// independent of whether any enrichment run happened recently.
function searchProbe(name) {
  const rows = nodeAll(name);
  const row = rows[0];
  const raw = row && row.json;
  if (!row) return { configured: true, status: null, value: null };
  if (raw && raw.error) return { configured: true, status: httpStatus(raw), value: null };
  return { configured: true, status: 200, value: extractSearchTotal(raw) };
}

const creditRows = nodeAll("Build Credit Status");
const creditBody = (creditRows[0] && creditRows[0].json) || {};
const balances = Array.isArray(creditBody.balances) ? creditBody.balances : [];
const balanceByProvider = {};
for (const b of balances) balanceByProvider[b.provider] = b;

const companiesRequested = searchProbe("HS Requested Search (Companies)");
const companiesReview = searchProbe("HS Review Search (Companies)");
const contactsRequested = searchProbe("HS Requested Search (Contacts)");
const contactsReview = searchProbe("HS Review Search (Contacts)");

const health = ["lusha", "apollo", "zoominfo"].map((provider) => {
  const b = balanceByProvider[provider] || {};
  return { source: provider,
    ...deriveSourceHealth({ configured: b.configured === true, status: b.status, value: b.credits }) };
});
// HubSpot's own credential health: the requested-companies probe is the canonical
// signal — same credential as all four searches, so a refusal there IS the HubSpot
// credential-health finding (D-08).
health.push({ source: "hubspot", ...deriveSourceHealth(companiesRequested) });

const body = buildStatusBody({
  counts: {
    companies_requested_unresolved: companiesRequested.value,
    companies_awaiting_review: companiesReview.value,
    contacts_requested_unresolved: contactsRequested.value,
    contacts_awaiting_review: contactsReview.value,
  },
  health,
  checked_at: creditBody.checked_at,
});

return [{ json: { ...body, balances } }];
